"""Home fixed navigation, fading content, themed listbox and readable feedback."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);p.add_argument('--url');a=p.parse_args();out=a.output.resolve();out.mkdir(parents=True,exist_ok=False);root=Path(__file__).resolve().parents[1]
with sync_playwright() as pw:
 b=pw.chromium.launch(channel='msedge',headless=True);page=b.new_page(viewport={'width':1375,'height':884},reduced_motion='reduce');errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(a.url or (root/'SkyMusicStudio_Standalone.html').as_uri());page.wait_for_timeout(500)
 header=page.locator('.home-top');before=header.bounding_box();hero_before=page.locator('.theme-carousel').bounding_box();page.locator('#homeView').evaluate('e=>e.scrollTop=220');page.wait_for_timeout(150);after=header.bounding_box();hero_after=page.locator('.theme-carousel').bounding_box();assert abs(after['y']-before['y'])<1,(before,after);assert hero_after['y']<hero_before['y']-50
 fade=page.locator('.home-body').evaluate("e=>({mask:getComputedStyle(e).maskImage,clip:getComputedStyle(e).clipPath,cutoff:parseFloat(e.style.getPropertyValue('--home-content-cutoff'))})");assert fade['cutoff']>40 and 'linear-gradient' in fade['mask'] and 'inset' in fade['clip'],fade
 add=page.locator('#libraryCards .add-card');assert add.inner_text()=='导入新的乐曲';centers=add.evaluate("e=>{const r=e.getBoundingClientRect(),a=e.querySelector('.plus').getBoundingClientRect(),b=e.querySelector('strong').getBoundingClientRect();return {outer:(r.top+r.bottom)/2,inner:(a.top+b.bottom)/2,x:r.left+r.width/2,text:b.left+b.width/2}} ");assert abs(centers['outer']-centers['inner'])<2 and abs(centers['x']-centers['text'])<2,centers
 page.screenshot(path=str(out/'home-scrolled.png'));page.locator('#showGuide').hover();hover=page.locator('#showGuide').evaluate('e=>getComputedStyle(e).backgroundColor');assert hover!='rgb(49, 84, 73)',hover;page.locator('#showGuide').click();assert page.locator('#helpDialog').is_visible();page.keyboard.press('Escape')
 page.locator('#homeView').evaluate('e=>e.scrollTop=0');page.wait_for_timeout(150);assert page.locator('.home-body').evaluate('e=>getComputedStyle(e).maskImage')=='none'
 trigger=page.locator('#libraryFilterToggle');trigger.click();assert page.locator('#libraryFilterMenu:popover-open').is_visible();page.screenshot(path=str(out/'home-filter-open.png'));page.keyboard.press('ArrowDown');page.keyboard.press('Enter');assert page.locator('#libraryFilter').input_value()=='favorite';assert page.locator('#libraryCards .light-cone').count()==0
 trigger.click();page.keyboard.press('Home');page.keyboard.press('Enter');assert page.locator('#libraryCards .light-cone').count()==6
 trigger.click();page.keyboard.press('Escape');assert trigger.get_attribute('aria-expanded')=='false';count=page.locator('#libraryCount').evaluate("e=>({color:getComputedStyle(e).color,weight:getComputedStyle(e).fontWeight,bg:getComputedStyle(e).backgroundColor})");assert count['color']=='rgb(240, 248, 255)' and int(count['weight'])>=600,count
 shadow=page.locator('.theme-preview-open').filter(visible=True).first.evaluate('e=>getComputedStyle(e).boxShadow');assert shadow!='none'
 page.locator('.card-play').first.click();page.locator('#backLibrary').click();assert trigger.inner_text()=='全部曲目';assert page.locator('#homeView').evaluate('e=>e.scrollTop')==0
 page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(100);mobile_before=header.bounding_box();page.locator('#homeView').evaluate('e=>e.scrollTop=300');page.wait_for_timeout(150);assert page.locator('#homeView').evaluate('e=>e.scrollTop')>=299;mobile_after=header.bounding_box();assert abs(mobile_before['y']-mobile_after['y'])<1,(mobile_before,mobile_after);assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path=str(out/'mobile-fixed-header.png'))
 assert not errors,errors;b.close()
(out/'results.json').write_text(json.dumps({'passed':True,'headerBefore':before,'headerAfter':after,'fade':fade,'guideHover':hover,'count':count,'themeButtonShadow':shadow,'errors':errors},ensure_ascii=False,indent=2),'utf-8');print('PASS pinned desktop/mobile header, content fade, themed keyboard filter, count contrast, button depth and return reset')
